/* ع القهوة: أجواء الصفحة الرئيسية مع راديو شعبي FM 95 */
(()=>{
 if(document.getElementById('ahwa-home-radio'))return;
 const wrap=document.createElement('aside');wrap.id='ahwa-home-radio';
 wrap.style.cssText='position:fixed;left:14px;bottom:14px;z-index:9999;direction:rtl;display:flex;align-items:center;gap:8px;flex-wrap:wrap;background:#201008ed;color:#ffe6aa;border:1px solid #dfac53;border-radius:16px;padding:10px 12px;box-shadow:0 7px 24px #0008;font:700 13px Cairo,Tahoma,sans-serif;max-width:min(450px,92vw)';
 wrap.innerHTML='<span>☕ أجواء القهوة + شعبي FM 95</span><button id="ahwa-home-start" style="background:#d8a24c;color:#170b04;border:0;border-radius:8px;padding:7px 11px;cursor:pointer">▶ تشغيل القعدة</button><button id="ahwa-home-stop" style="background:#30170a;color:#ffe4a5;border:1px solid #a67b37;border-radius:8px;padding:7px;cursor:pointer">■ إيقاف</button><a href="https://worldradiomap.com/eg/play/sha3by" target="_blank" rel="noopener" style="color:#ffe4a5">فتح شعبي FM ↗</a><small id="ahwa-home-message" style="width:100%;font-size:11px;color:#d4be91">قد يمنع المتصفح بدء الصوت قبل أول ضغطة.</small>';
 document.body.append(wrap);
 const ambience=new Audio('data:audio/wav;base64,');ambience.loop=true;ambience.volume=.16;
 let frame=null;
 const message=wrap.querySelector('#ahwa-home-message');
 async function start(){
  try{await ambience.play()}catch(e){message.textContent='اضغط تشغيل لتفعيل أجواء القهوة.'}
  if(!frame){frame=document.createElement('iframe');frame.title='شعبي FM 95';frame.allow='autoplay';frame.src='https://worldradiomap.com/eg/play/sha3by';frame.style.cssText='width:100%;height:125px;border:1px solid #76532d;border-radius:8px;background:#fff';wrap.append(frame)}
  message.textContent='أجواء القهوة تعمل. اضغط تشغيل من مشغل المحطة إن لم يبدأ بث الراديو.';
 }
 function stop(){ambience.pause();if(frame){frame.remove();frame=null}message.textContent='تم إيقاف الأجواء والراديو.'}
 wrap.querySelector('#ahwa-home-start').onclick=start;
 wrap.querySelector('#ahwa-home-stop').onclick=stop;
 // Browsers require a gesture for audible playback.
 document.addEventListener('pointerdown',function once(e){if(e.target.closest('#ahwa-home-stop'))return;start();document.removeEventListener('pointerdown',once)}, {passive:true});
})();